package com.clipforge.mobile
import androidx.compose.foundation.Canvas
import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import java.io.File
object EditingChecks {
    fun captions(clip:TimelineClip):List<String> = buildList{clip.subtitles.forEachIndexed{i,c->if(c.text.isBlank())add("Line ${i+1}: empty text");if(c.startMs<clip.startMs||c.endMs>clip.endMs)add("Line ${i+1}: partly outside this cut");if(c.text.length>90||c.text.trim().split(Regex("\\s+")).size>14)add("Line ${i+1}: shorten or split this caption");if(c.endMs-c.startMs<200||c.text.length*1000.0/(c.endMs-c.startMs).coerceAtLeast(1)>28)add("Line ${i+1}: may be too fast to read");if(i>0&&c.startMs<clip.subtitles[i-1].endMs)add("Line ${i+1}: overlaps previous caption")}}.distinct().take(50)
    fun removeSilence(clips:List<TimelineClip>,id:String,region:AudioRegion):List<TimelineClip>{val clip=clips.firstOrNull{it.id==id}?:error("Select a cut");require(AudioPlanning.silence(clip).any{it==region}){"Reanalyze this gap"};val parts=buildList{if(region.startMs>clip.startMs)add(clip.trimmed(clip.startMs,region.startMs).copy(transition=CutTransition()));if(region.endMs<clip.endMs)add(clip.copy(id=java.util.UUID.randomUUID().toString()).trimmed(region.endMs,clip.endMs))};return clips.flatMap{if(it.id==id)parts else listOf(it)}.also{require(it.size<=60){"Gap removal exceeds 60 cuts"}}}
    fun posting(p:EditorProject):String{val text=p.campaignBrief.postingCaption.trim().ifBlank{p.timelineClips.firstOrNull()?.hook.orEmpty().ifBlank{p.hook}};val tokens=text.lowercase().split(Regex("\\s+"));return (listOf(text)+p.campaignBrief.tags.split(Regex("\\s+")).filter{it.isNotBlank()&&it.lowercase() !in tokens}).filter(String::isNotBlank).joinToString(" ").trim()}
    fun estimateBytes(ms:Long)=ms.coerceIn(0,21_600_000)*1550+16L*1024*1024
    fun cleanTemporary(cache:File,now:Long=System.currentTimeMillis()):Long{var removed=0L;cache.listFiles().orEmpty().filter{it.isFile&&it.lastModified()<now-3600000&&listOf("audio-inspect-","whisper_chunk_","music-beat-").any{prefix->it.name.startsWith(prefix)}}.forEach{f->val size=f.length();if(f.delete())removed+=size};return removed}
}
@Composable fun SafeAreaGuide(modifier:Modifier=Modifier){Canvas(modifier){val left=size.width*.08f;val top=size.height*.12f;val right=size.width*.85f;val bottom=size.height*.8f;drawRect(Color.Red.copy(alpha=.12f),size=androidx.compose.ui.geometry.Size(size.width,top));drawRect(Color.Red.copy(alpha=.12f),topLeft=androidx.compose.ui.geometry.Offset(right,0f),size=androidx.compose.ui.geometry.Size(size.width-right,size.height));drawRect(Color.Red.copy(alpha=.12f),topLeft=androidx.compose.ui.geometry.Offset(0f,bottom),size=androidx.compose.ui.geometry.Size(size.width,size.height-bottom));drawRect(Color.Cyan.copy(alpha=.7f),topLeft=androidx.compose.ui.geometry.Offset(left,top),size=androidx.compose.ui.geometry.Size(right-left,bottom-top),style=androidx.compose.ui.graphics.drawscope.Stroke(2f))}}
@Composable fun CaptionProofreading(clip:TimelineClip){var show by remember{mutableStateOf(false)};val issues=remember(clip.subtitles,clip.startMs,clip.endMs){EditingChecks.captions(clip)};TextButton(onClick={show=!show}){Text("Caption check · ${issues.size} notes")};if(show){if(issues.isEmpty())Text("No timing/readability flags. Review spelling and context manually.",style=MaterialTheme.typography.bodySmall) else issues.forEach{Text(it,style=MaterialTheme.typography.bodySmall)}}}
@Composable fun BatchPresetControls(clips:List<TimelineClip>,presets:List<EditingPreset>,enabled:Boolean,onApply:(Set<String>,EditingPreset)->Unit){var show by remember{mutableStateOf(false)};var selected by remember{mutableStateOf(emptySet<String>())};TextButton(onClick={show=!show}){Text("Batch styling")};if(show){Text("Caption/canvas settings are project-wide; selected cuts receive the preset look, motion and SFX.");clips.chunked(4).forEach{row->Row{row.forEach{clip->FilterChip(clip.id in selected,{selected=if(clip.id in selected)selected-clip.id else selected+clip.id},enabled=enabled,label={Text("Clip ${clips.indexOf(clip)+1}")})}}};presets.forEach{p->OutlinedButton(enabled=enabled&&selected.any{id->clips.any{it.id==id}},onClick={onApply(selected,p)}){Text("Apply ${p.name} to selected cuts")}};if(presets.isEmpty())Text("Save an editing preset first.")}}
